using CsvHelper;
using CsvHelper.Configuration;
using Financeiro.Application;
using Financeiro.Domain;
using Financeiro.Infrastructure;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.RateLimiting;
using Microsoft.EntityFrameworkCore;
using System.Globalization;
using System.Text;
using System.Data;

namespace Financeiro.Api.Controllers;

[ApiController,Authorize,Route("api/v1/debts")]
public sealed class DebtsController(FinanceiroDbContext db,ICurrentUser current):ControllerBase
{
 [HttpGet]public async Task<IActionResult>List(CancellationToken ct){var today=DateOnly.FromDateTime(DateTime.UtcNow);var debts=await db.Debts.AsNoTracking().Include(x=>x.Installments).ToListAsync(ct);return Ok(debts.Select(x=>ToResponse(x,today)));}
 [HttpGet("{id:guid}")]public async Task<IActionResult>Get(Guid id,CancellationToken ct){var today=DateOnly.FromDateTime(DateTime.UtcNow);var d=await db.Debts.AsNoTracking().Include(x=>x.Installments).SingleOrDefaultAsync(x=>x.Id==id,ct);return d is null?NotFound():Ok(ToResponse(d,today));}
 [HttpPost]public async Task<IActionResult>Create(DebtRequest r,CancellationToken ct){if(!Valid(r))return BadRequest("Dívida inválida.");var d=new Debt{UserId=current.UserId,Name=r.Name.Trim(),Type=r.Type,Principal=r.Principal,InterestRate=r.InterestRate,InstallmentCount=r.InstallmentCount,StartDate=r.StartDate};var amounts=FinancialCalculations.SplitAmount(r.Principal,r.InstallmentCount);for(var i=1;i<=r.InstallmentCount;i++)d.Installments.Add(new DebtInstallment{UserId=current.UserId,Number=i,Amount=amounts[i-1],DueDate=r.StartDate.AddMonths(i)});db.Add(d);await db.SaveChangesAsync(ct);return Ok(d);}
 [HttpPut("{id:guid}")]public async Task<IActionResult>Update(Guid id,DebtRequest r,CancellationToken ct){var d=await db.Debts.Include(x=>x.Installments).SingleOrDefaultAsync(x=>x.Id==id,ct);if(d is null)return NotFound();if(!Valid(r))return BadRequest("Dívida inválida.");if(d.Installments.Any(x=>x.PaidAt is not null))return Conflict("Não é possível alterar uma dívida com parcelas pagas.");d.Name=r.Name.Trim();d.Type=r.Type;d.Principal=r.Principal;d.InterestRate=r.InterestRate;d.InstallmentCount=r.InstallmentCount;d.StartDate=r.StartDate;db.DebtInstallments.RemoveRange(d.Installments);var amounts=FinancialCalculations.SplitAmount(r.Principal,r.InstallmentCount);for(var i=1;i<=r.InstallmentCount;i++)d.Installments.Add(new DebtInstallment{UserId=current.UserId,Number=i,Amount=amounts[i-1],DueDate=r.StartDate.AddMonths(i)});await db.SaveChangesAsync(ct);return Ok(d);}
 [HttpPost("{id:guid}/installments/{installmentId:guid}/pay")]public async Task<IActionResult>PayInstallment(Guid id,Guid installmentId,InvoicePaymentRequest r,CancellationToken ct){await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable,ct);var installment=await db.DebtInstallments.SingleOrDefaultAsync(x=>x.Id==installmentId&&x.DebtId==id,ct);if(installment is null)return NotFound();if(installment.PaidAt is not null)return Conflict("Parcela já paga.");if(r.PaymentDate<new DateOnly(2000,1,1))return BadRequest("Data de pagamento inválida.");if(!await db.Accounts.AnyAsync(x=>x.Id==r.AccountId&&x.IsActive,ct))return BadRequest("Conta inválida.");var transaction=new Transaction{UserId=current.UserId,AccountId=r.AccountId,Description=$"Pagamento parcela {installment.Number}",Amount=installment.Amount,Type=TransactionType.Expense,Status=TransactionStatus.Paid,Date=r.PaymentDate,PaidAt=r.PaymentDate};db.Transactions.Add(transaction);installment.PaidAt=r.PaymentDate;await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return Ok(new DebtPaymentResponse(installment.Id,installment.Number,installment.Amount,installment.DueDate,installment.PaidAt.Value,transaction.Id));}
 [HttpDelete("{id:guid}")]public async Task<IActionResult>Delete(Guid id,CancellationToken ct){var d=await db.Debts.FindAsync([id],ct);if(d is null)return NotFound();db.Remove(d);await db.SaveChangesAsync(ct);return NoContent();}
 private static DebtResponse ToResponse(Debt debt,DateOnly today){var installments=debt.Installments.OrderBy(x=>x.Number).Select(x=>new DebtInstallmentResponse(x.Id,x.Number,x.Amount,x.DueDate,x.PaidAt,x.PaidAt is null&&x.DueDate<today)).ToArray();return new(debt.Id,debt.Name,debt.Type,debt.Principal,debt.InterestRate,debt.InstallmentCount,debt.StartDate,installments.Where(x=>x.PaidAt is not null).Sum(x=>x.Amount),installments.Where(x=>x.PaidAt is null).Sum(x=>x.Amount),installments.Count(x=>x.PaidAt is not null),installments.Count(x=>x.PaidAt is null),installments.Where(x=>x.PaidAt is null).Select(x=>(DateOnly?)x.DueDate).FirstOrDefault(),installments);}
 private static bool Valid(DebtRequest r)=>!string.IsNullOrWhiteSpace(r.Name)&&r.Name.Trim().Length<=160&&r.Principal>0&&r.InterestRate>=0&&r.InstallmentCount is>=1 and<=600;
}

[ApiController,Authorize,Route("api/v1/subscriptions")]
public sealed class SubscriptionsController(FinanceiroDbContext db,ICurrentUser current):ControllerBase
{
 [HttpGet]public async Task<IActionResult>List(CancellationToken ct){var today=DateOnly.FromDateTime(DateTime.UtcNow);var rows=await db.Subscriptions.AsNoTracking().ToListAsync(ct);return Ok(rows.Select(x=>new{Id=x.Id,Name=x.Name,Amount=x.Amount,Cycle=x.Cycle,BillingDay=x.BillingDay,StartDate=x.StartDate,AccountId=x.AccountId,CategoryId=x.CategoryId,IsActive=x.IsActive,NextBillingDate=x.IsActive?FinancialCalculations.NextBillingDate(x.StartDate,x.Cycle,x.BillingDay,today):null}));}
 [HttpPost]public async Task<IActionResult>Create(SubscriptionRequest r,CancellationToken ct){if(!Valid(r)||!await RelatedIdsBelongToUser(r.AccountId,r.CategoryId,ct))return BadRequest("Assinatura inválida.");var x=new Subscription{UserId=current.UserId,Name=r.Name.Trim(),Amount=r.Amount,Cycle=r.Cycle,BillingDay=r.BillingDay,StartDate=r.StartDate,AccountId=r.AccountId,CategoryId=r.CategoryId,IsActive=r.IsActive};db.Add(x);await db.SaveChangesAsync(ct);return Ok(x);}
 [HttpPut("{id:guid}")]public async Task<IActionResult>Update(Guid id,SubscriptionRequest r,CancellationToken ct){var x=await db.Subscriptions.FindAsync([id],ct);if(x is null)return NotFound();if(!Valid(r)||!await RelatedIdsBelongToUser(r.AccountId,r.CategoryId,ct))return BadRequest("Assinatura inválida.");x.Name=r.Name.Trim();x.Amount=r.Amount;x.Cycle=r.Cycle;x.BillingDay=r.BillingDay;x.StartDate=r.StartDate;x.AccountId=r.AccountId;x.CategoryId=r.CategoryId;x.IsActive=r.IsActive;await db.SaveChangesAsync(ct);return Ok(x);}
 private async Task<bool> RelatedIdsBelongToUser(Guid? accountId,Guid? categoryId,CancellationToken ct)=> (accountId is null||await db.Accounts.AnyAsync(x=>x.Id==accountId&&x.IsActive,ct))&&(categoryId is null||await db.Categories.AnyAsync(x=>x.Id==categoryId&&x.Type==TransactionType.Expense&&x.IsActive,ct));
 [HttpDelete("{id:guid}")]public async Task<IActionResult>Delete(Guid id,CancellationToken ct){var x=await db.Subscriptions.FindAsync([id],ct);if(x is null)return NotFound();db.Remove(x);await db.SaveChangesAsync(ct);return NoContent();}
 private static bool Valid(SubscriptionRequest r)=>!string.IsNullOrWhiteSpace(r.Name)&&r.Name.Trim().Length<=160&&r.Amount>0&&Enum.IsDefined(typeof(SubscriptionCycle),r.Cycle)&&r.BillingDay is>=1 and<=31;
}

[ApiController,Authorize,Route("api/v1/credit-cards")]
public sealed class CreditCardsController(FinanceiroDbContext db,ICurrentUser current):ControllerBase
{
 [HttpGet]public async Task<IActionResult>List(CancellationToken ct){var today=DateOnly.FromDateTime(DateTime.UtcNow);var cards=await db.CreditCards.AsNoTracking().Include(x=>x.Invoices).ThenInclude(i=>i.Installments).ThenInclude(i=>i.Purchase).ToListAsync(ct);return Ok(cards.Select(x=>ToResponse(x,today)));}
 [HttpGet("{id:guid}")]public async Task<IActionResult>Get(Guid id,CancellationToken ct){var today=DateOnly.FromDateTime(DateTime.UtcNow);var card=await db.CreditCards.AsNoTracking().Include(x=>x.Invoices).ThenInclude(x=>x.Installments).ThenInclude(x=>x.Purchase).SingleOrDefaultAsync(x=>x.Id==id,ct);return card is null?NotFound():Ok(ToResponse(card,today));}
 [HttpPost]public async Task<IActionResult>Create(CreditCardRequest r,CancellationToken ct){if(Validate(r) is{}error)return BadRequest(error);var x=new CreditCard{UserId=current.UserId,Name=r.Name.Trim(),Bank=r.Bank.Trim(),Brand=r.Brand,Limit=r.Limit,BestPurchaseDay=r.BestPurchaseDay,ClosingDay=r.ClosingDay,DueDay=r.DueDay,IsActive=r.IsActive};db.Add(x);await db.SaveChangesAsync(ct);return Ok(ToMutationResponse(x));}
 [HttpPut("{id:guid}")]public async Task<IActionResult>Update(Guid id,CreditCardRequest r,CancellationToken ct){var x=await db.CreditCards.FindAsync([id],ct);if(x is null)return NotFound();if(Validate(r) is{}error)return BadRequest(error);x.Name=r.Name.Trim();x.Bank=r.Bank.Trim();x.Brand=r.Brand;x.Limit=r.Limit;x.BestPurchaseDay=r.BestPurchaseDay;x.ClosingDay=r.ClosingDay;x.DueDay=r.DueDay;x.IsActive=r.IsActive;await db.SaveChangesAsync(ct);return Ok(ToMutationResponse(x));}
 [HttpDelete("{id:guid}")]public async Task<IActionResult>Delete(Guid id,CancellationToken ct){var x=await db.CreditCards.Include(c=>c.Invoices).SingleOrDefaultAsync(c=>c.Id==id,ct);if(x is null)return NotFound();if(x.Invoices.Count>0){x.IsActive=false;await db.SaveChangesAsync(ct);return NoContent();}db.Remove(x);await db.SaveChangesAsync(ct);return NoContent();}
 private static string? Validate(CreditCardRequest r)=>string.IsNullOrWhiteSpace(r.Name)||r.Name.Trim().Length>120?"Nome do cartão inválido.":string.IsNullOrWhiteSpace(r.Bank)||r.Bank.Trim().Length>120?"Instituição inválida.":r.Limit<0||r.BestPurchaseDay is<1 or>31||r.ClosingDay is<1 or>31||r.DueDay is<1 or>31?"Cartão inválido.":null;
 private static InvoiceStatus EffectiveInvoiceStatus(CreditCardInvoice invoice,DateOnly today)=>invoice.PaidAt is not null?InvoiceStatus.Paid:invoice.DueDate<today?InvoiceStatus.Overdue:invoice.ClosingDate<today?InvoiceStatus.Closed:InvoiceStatus.Open;
 private static CreditCardMutationResponse ToMutationResponse(CreditCard card)=>new(card.Id,card.Name,card.Bank,card.Brand,card.Limit,card.BestPurchaseDay,card.ClosingDay,card.DueDay,card.IsActive);
 private static CreditCardResponse ToResponse(CreditCard card,DateOnly today){var used=card.Invoices.Where(i=>i.PaidAt is null).SelectMany(i=>i.Installments).Sum(i=>i.Amount);return new(card.Id,card.Name,card.Bank,card.Brand,card.Limit,card.BestPurchaseDay,card.ClosingDay,card.DueDay,card.IsActive,used,card.Limit-used,card.Invoices.OrderByDescending(i=>i.Year).ThenByDescending(i=>i.Month).Select(i=>new CreditCardInvoiceResponse(i.Id,i.CreditCardId,i.Month,i.Year,i.ClosingDate,i.DueDate,EffectiveInvoiceStatus(i,today),i.Installments.Sum(x=>x.Amount),i.PaidAt,i.PaymentTransactionId,i.Installments.OrderBy(x=>x.Number).Select(x=>new CreditCardInstallmentResponse(x.Id,x.Number,x.Total,x.Amount,x.CreditCardInvoiceId,x.Purchase!.Description)).ToArray())).ToArray());}
 [HttpPost("{id:guid}/purchases")]public async Task<IActionResult>Purchase(Guid id,CardPurchaseRequest r,CancellationToken ct){if(string.IsNullOrWhiteSpace(r.Description)||r.Description.Trim().Length>200||r.TotalAmount<=0||r.InstallmentCount is<1 or>60)return BadRequest("Compra inválida.");var card=await db.CreditCards.SingleOrDefaultAsync(x=>x.Id==id&&x.IsActive,ct);if(card is null)return NotFound();if(r.CategoryId is not null&&!await db.Categories.AnyAsync(x=>x.Id==r.CategoryId&&x.Type==TransactionType.Expense&&x.IsActive,ct))return BadRequest("Categoria inválida.");await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable,ct);var purchase=new CreditCardPurchase{UserId=current.UserId,CreditCardId=id,Description=r.Description.Trim(),TotalAmount=r.TotalAmount,PurchaseDate=r.PurchaseDate,CategoryId=r.CategoryId,InstallmentCount=r.InstallmentCount};var amounts=FinancialCalculations.SplitAmount(r.TotalAmount,r.InstallmentCount);var period=FinancialCalculations.InvoicePeriod(r.PurchaseDate,card.ClosingDay);var invoices=new Dictionary<(int Month,int Year),CreditCardInvoice>();for(var i=1;i<=r.InstallmentCount;i++){var date=new DateOnly(period.Year,period.Month,1).AddMonths(i-1);var key=(date.Month,date.Year);if(!invoices.TryGetValue(key,out var inv)){inv=await db.CreditCardInvoices.SingleOrDefaultAsync(x=>x.CreditCardId==id&&x.Month==key.Month&&x.Year==key.Year,ct);if(inv is null){inv=new CreditCardInvoice{UserId=current.UserId,CreditCardId=id,Month=key.Month,Year=key.Year,ClosingDate=FinancialCalculations.InvoiceClosingDate(date.Year,date.Month,card.ClosingDay),DueDate=FinancialCalculations.InvoiceDueDate(date.Year,date.Month,card.DueDay),Status=InvoiceStatus.Open};db.CreditCardInvoices.Add(inv);}invoices[key]=inv;}purchase.Installments.Add(new Installment{UserId=current.UserId,CreditCardPurchaseId=purchase.Id,Invoice=inv,Number=i,Total=r.InstallmentCount,Amount=amounts[i-1]});}db.Add(purchase);await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return Ok(new CreditCardPurchaseResponse(purchase.Id,purchase.CreditCardId,purchase.Description,purchase.TotalAmount,purchase.PurchaseDate,purchase.CategoryId,purchase.InstallmentCount,purchase.Installments.Select(x=>new CreditCardInstallmentResponse(x.Id,x.Number,x.Total,x.Amount,x.CreditCardInvoiceId,null)).ToArray()));}
 [HttpGet("{id:guid}/purchases")]public async Task<IActionResult>Purchases(Guid id,CancellationToken ct){if(!await db.CreditCards.AnyAsync(x=>x.Id==id,ct))return NotFound();var purchases=await db.CreditCardPurchases.AsNoTracking().Where(x=>x.CreditCardId==id).Include(x=>x.Installments).OrderByDescending(x=>x.PurchaseDate).ToListAsync(ct);return Ok(purchases.Select(x=>new CreditCardPurchaseResponse(x.Id,x.CreditCardId,x.Description,x.TotalAmount,x.PurchaseDate,x.CategoryId,x.InstallmentCount,x.Installments.OrderBy(i=>i.Number).Select(i=>new CreditCardInstallmentResponse(i.Id,i.Number,i.Total,i.Amount,i.CreditCardInvoiceId,null)).ToArray())));}
 [HttpGet("{id:guid}/invoices")]public async Task<IActionResult>Invoices(Guid id,CancellationToken ct){if(!await db.CreditCards.AnyAsync(x=>x.Id==id,ct))return NotFound();var today=DateOnly.FromDateTime(DateTime.UtcNow);var invoices=await db.CreditCardInvoices.AsNoTracking().Where(x=>x.CreditCardId==id).Include(x=>x.Installments).ThenInclude(x=>x.Purchase).OrderByDescending(x=>x.Year).ThenByDescending(x=>x.Month).ToListAsync(ct);return Ok(invoices.Select(x=>new CreditCardInvoiceResponse(x.Id,x.CreditCardId,x.Month,x.Year,x.ClosingDate,x.DueDate,EffectiveInvoiceStatus(x,today),x.Installments.Sum(i=>i.Amount),x.PaidAt,x.PaymentTransactionId,x.Installments.OrderBy(i=>i.Number).Select(i=>new CreditCardInstallmentResponse(i.Id,i.Number,i.Total,i.Amount,i.CreditCardInvoiceId,i.Purchase!.Description)).ToArray())).ToArray());}
 [HttpGet("invoices/{invoiceId:guid}")]public async Task<IActionResult>Invoice(Guid invoiceId,CancellationToken ct){var today=DateOnly.FromDateTime(DateTime.UtcNow);var inv=await db.CreditCardInvoices.AsNoTracking().Include(x=>x.CreditCard).Include(x=>x.Installments).ThenInclude(x=>x.Purchase).SingleOrDefaultAsync(x=>x.Id==invoiceId,ct);return inv is null?NotFound():Ok(new CreditCardInvoiceResponse(inv.Id,inv.CreditCardId,inv.Month,inv.Year,inv.ClosingDate,inv.DueDate,EffectiveInvoiceStatus(inv,today),inv.Installments.Sum(i=>i.Amount),inv.PaidAt,inv.PaymentTransactionId,inv.Installments.OrderBy(i=>i.Number).Select(i=>new CreditCardInstallmentResponse(i.Id,i.Number,i.Total,i.Amount,i.CreditCardInvoiceId,i.Purchase!.Description)).ToArray()));}
 [HttpPost("invoices/{invoiceId:guid}/pay")]public async Task<IActionResult>PayInvoice(Guid invoiceId,InvoicePaymentRequest r,CancellationToken ct){await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable,ct);var inv=await db.CreditCardInvoices.Include(x=>x.Installments).SingleOrDefaultAsync(x=>x.Id==invoiceId,ct);if(inv is null)return NotFound();if(inv.PaidAt is not null||EffectiveInvoiceStatus(inv,DateOnly.FromDateTime(DateTime.UtcNow))==InvoiceStatus.Paid)return Conflict("Fatura já paga.");if(r.PaymentDate<new DateOnly(2000,1,1))return BadRequest("Data de pagamento inválida.");if(!await db.Accounts.AnyAsync(x=>x.Id==r.AccountId&&x.IsActive,ct))return BadRequest("Conta inválida.");var amount=inv.Installments.Sum(x=>x.Amount);var payment=new Transaction{UserId=current.UserId,AccountId=r.AccountId,Description=$"Pagamento fatura {inv.Month:D2}/{inv.Year}",Amount=amount,Type=TransactionType.Expense,Status=TransactionStatus.Paid,Date=r.PaymentDate,PaidAt=r.PaymentDate};db.Transactions.Add(payment);inv.PaymentTransactionId=payment.Id;inv.Status=InvoiceStatus.Paid;inv.PaidAt=r.PaymentDate;await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return Ok(new InvoicePaymentResponse(inv.Id,inv.Month,inv.Year,inv.PaidAt.Value,InvoiceStatus.Paid,amount,payment.Id));}
}

[ApiController,Authorize,EnableRateLimiting("expensive"),Route("api/v1/reports")]
public sealed class ReportsController(FinanceiroDbContext db):ControllerBase
{
 [HttpGet("summary")]public async Task<IActionResult>Summary(DateOnly? from,DateOnly? to,Guid? accountId,CancellationToken ct){var start=from??DateOnly.FromDateTime(DateTime.UtcNow.AddMonths(-11));var end=to??DateOnly.FromDateTime(DateTime.UtcNow);if(start>end||end.DayNumber-start.DayNumber>366)return BadRequest("Intervalo de relatório inválido.");if(accountId is not null&&!await db.Accounts.AnyAsync(x=>x.Id==accountId&&x.IsActive,ct))return NotFound();var txQuery=db.Transactions.AsNoTracking().Include(x=>x.Category).Where(x=>x.Date>=start&&x.Date<=end&&x.Status!=TransactionStatus.Cancelled);if(accountId is not null)txQuery=txQuery.Where(x=>x.AccountId==accountId);var tx=await txQuery.ToListAsync(ct);var monthly=tx.GroupBy(x=>new{x.Date.Year,x.Date.Month}).OrderBy(g=>g.Key.Year).ThenBy(g=>g.Key.Month).Select(g=>new{month=$"{g.Key.Month:D2}/{g.Key.Year}",income=g.Where(x=>x.Type==TransactionType.Income).Sum(x=>x.Amount),expense=g.Where(x=>x.Type==TransactionType.Expense).Sum(x=>x.Amount)}).ToList();var categories=tx.Where(x=>x.Type==TransactionType.Expense).GroupBy(x=>x.Category?.Name??"Outros").Select(g=>new{category=g.Key,value=g.Sum(x=>x.Amount)}).ToList();var cards=accountId is not null?[]:await db.CreditCardInvoices.AsNoTracking().Include(x=>x.CreditCard).Include(x=>x.Installments).Where(x=>x.DueDate>=start&&x.DueDate<=end).GroupBy(x=>x.CreditCard!.Name).Select(g=>new{card=g.Key,value=g.SelectMany(x=>x.Installments).Sum(i=>i.Amount)}).ToListAsync(ct);return Ok(new{from=start,to=end,accountId,monthly,categories,cards});}
}

[ApiController,Authorize,EnableRateLimiting("search"),Route("api/v1/search")]
public sealed class SearchController(FinanceiroDbContext db):ControllerBase
{
 [HttpGet]public async Task<IActionResult>Search(string? q,int limit=10,CancellationToken ct=default){q=q?.Trim();if(string.IsNullOrWhiteSpace(q)||q.Length<2)return Ok(Array.Empty<GlobalSearchResult>());q=q[..Math.Min(q.Length,80)];var pattern=$"%{q}%";limit=Math.Clamp(limit,1,50);var results=new List<GlobalSearchResult>();var transactionResults=await db.Transactions.Where(x=>EF.Functions.ILike(x.Description,pattern)||(x.Notes!=null&&EF.Functions.ILike(x.Notes,pattern))||(x.Tags!=null&&EF.Functions.ILike(x.Tags,pattern))).Take(limit).Select(x=>new{x.Id,x.Description,x.Date,x.Amount,x.Type}).ToListAsync(ct);results.AddRange(transactionResults.Select(x=>new GlobalSearchResult("transaction",x.Id,x.Description,x.Date.ToString("dd/MM/yyyy"),x.Type==TransactionType.Expense?-x.Amount:x.Amount,"/transacoes")));results.AddRange(await db.Accounts.Where(x=>EF.Functions.ILike(x.Name,pattern)||(x.Institution!=null&&EF.Functions.ILike(x.Institution,pattern))).Take(limit).Select(x=>new GlobalSearchResult("account",x.Id,x.Name,x.Institution??"Conta",null,"/contas")).ToListAsync(ct));results.AddRange(await db.Categories.Where(x=>EF.Functions.ILike(x.Name,pattern)).Take(limit).Select(x=>new GlobalSearchResult("category",x.Id,x.Name,x.Type.ToString(),null,"/categorias")).ToListAsync(ct));results.AddRange(await db.CreditCards.Where(x=>EF.Functions.ILike(x.Name,pattern)||EF.Functions.ILike(x.Bank,pattern)).Take(limit).Select(x=>new GlobalSearchResult("card",x.Id,x.Name,x.Bank,null,"/cartoes")).ToListAsync(ct));results.AddRange(await db.Debts.Where(x=>EF.Functions.ILike(x.Name,pattern)).Take(limit).Select(x=>new GlobalSearchResult("debt",x.Id,x.Name,x.Type.ToString(),x.Principal,"/dividas")).ToListAsync(ct));results.AddRange(await db.Subscriptions.Where(x=>EF.Functions.ILike(x.Name,pattern)).Take(limit).Select(x=>new GlobalSearchResult("subscription",x.Id,x.Name,x.Cycle.ToString(),x.Amount,"/assinaturas")).ToListAsync(ct));results.AddRange(await db.Investments.Where(x=>EF.Functions.ILike(x.Asset,pattern)||(x.Broker!=null&&EF.Functions.ILike(x.Broker,pattern))).Take(limit).Select(x=>new GlobalSearchResult("investment",x.Id,x.Asset,x.Broker??x.Type.ToString(),x.Quantity*x.CurrentPrice,"/investimentos")).ToListAsync(ct));results.AddRange(await db.FinancialGoals.Where(x=>EF.Functions.ILike(x.Name,pattern)).Take(limit).Select(x=>new GlobalSearchResult("goal",x.Id,x.Name,"Meta financeira",x.TargetAmount,"/metas")).ToListAsync(ct));return Ok(results.Take(limit));}
}

[ApiController,Authorize,EnableRateLimiting("expensive"),Route("api/v1/calendar")]
public sealed class CalendarController(FinanceiroDbContext db):ControllerBase
{
 [HttpGet]public async Task<IActionResult>List(DateOnly? from,DateOnly? to,CancellationToken ct){var today=DateOnly.FromDateTime(DateTime.UtcNow);var start=from??new DateOnly(today.Year,today.Month,1);var end=to??start.AddMonths(1).AddDays(-1);if(start>end||end.DayNumber-start.DayNumber>365)return BadRequest("Intervalo de calendário inválido.");var events=new List<CalendarEventResponse>();var tx=await db.Transactions.AsNoTracking().Where(x=>x.DueDate!=null&&x.DueDate>=start&&x.DueDate<=end&&x.Status!=TransactionStatus.Cancelled).ToListAsync(ct);events.AddRange(tx.Select(x=>new CalendarEventResponse($"transaction:{x.Id}:{x.DueDate}",x.Id,"transaction","due-date",x.DueDate!.Value,x.Description,x.Type==TransactionType.Expense?-x.Amount:x.Amount,x.Status.ToString(),x.Status==TransactionStatus.Paid)));var installments=await db.DebtInstallments.AsNoTracking().Include(x=>x.Debt).Where(x=>x.PaidAt==null&&x.DueDate>=start&&x.DueDate<=end).ToListAsync(ct);events.AddRange(installments.Select(x=>new CalendarEventResponse($"debt:{x.Id}",x.DebtId,"debt-installment","debt-due",x.DueDate,$"{x.Debt!.Name} · parcela {x.Number}",x.Amount,x.DueDate<today?"overdue":"upcoming",false)));var invoices=await db.CreditCardInvoices.AsNoTracking().Include(x=>x.CreditCard).Include(x=>x.Installments).Where(x=>(x.DueDate>=start&&x.DueDate<=end)||(x.ClosingDate>=start&&x.ClosingDate<=end)).ToListAsync(ct);events.AddRange(invoices.Where(x=>x.ClosingDate>=start&&x.ClosingDate<=end).Select(x=>new CalendarEventResponse($"invoice:{x.Id}:closing",x.Id,"invoice","invoice-closing",x.ClosingDate,$"Fechamento · {x.CreditCard!.Name}",x.Installments.Sum(i=>i.Amount),"upcoming",false)));events.AddRange(invoices.Where(x=>x.DueDate>=start&&x.DueDate<=end).Select(x=>new CalendarEventResponse($"invoice:{x.Id}:due",x.Id,"invoice","invoice-due",x.DueDate,$"Vencimento · {x.CreditCard!.Name}",x.Installments.Sum(i=>i.Amount),x.PaidAt is not null?"paid":x.DueDate<today?"overdue":"upcoming",x.PaidAt is not null)));var subscriptions=await db.Subscriptions.AsNoTracking().Where(x=>x.IsActive&&x.StartDate<=end).ToListAsync(ct);foreach(var x in subscriptions)foreach(var date in FinancialCalculations.BillingOccurrences(x.StartDate,x.Cycle,x.BillingDay,start,end))events.Add(new CalendarEventResponse($"subscription:{x.Id}:{date}",x.Id,"subscription","subscription-billing",date,x.Name,x.Amount,"upcoming",false));return Ok(events.OrderBy(x=>x.Date).ThenBy(x=>x.Title));}
}

[ApiController,Authorize,Route("api/v1/notifications")]
public sealed class NotificationsController(FinanceiroDbContext db, ICurrentUser current):ControllerBase
{
 [HttpGet]public async Task<IActionResult>List(bool unreadOnly=false,CancellationToken ct=default){await EnsureNotifications(ct);var notifications=await db.Notifications.AsNoTracking().Where(x=>!unreadOnly||!x.IsRead).OrderByDescending(x=>x.CreatedAt).Take(100).Select(x=>new NotificationResponse(x.Id,x.Type,x.Title,x.Message,x.UniqueKey,x.IsRead,x.CreatedAt,x.ReadAt)).ToListAsync(ct);return Ok(new PagedResult<NotificationResponse>(notifications,1,100,notifications.Count));}
 [HttpPost("{id:guid}/read")]public async Task<IActionResult>Read(Guid id,CancellationToken ct){var x=await db.Notifications.FindAsync([id],ct);if(x is null)return NotFound();x.IsRead=true;x.ReadAt=DateTime.UtcNow;await db.SaveChangesAsync(ct);return NoContent();}
 private async Task EnsureNotifications(CancellationToken ct)
 {
  var today=DateOnly.FromDateTime(DateTime.UtcNow);var until=today.AddDays(7);var pending=new List<Notification>();
  var invoices=await db.CreditCardInvoices.AsNoTracking().Include(x=>x.CreditCard).Where(x=>x.PaidAt==null&&x.DueDate>=today&&x.DueDate<=until).ToListAsync(ct);pending.AddRange(invoices.Select(x=>New(NotificationType.Invoice,$"invoice:{x.Id}:due:{x.DueDate}","Fatura próxima do vencimento",$"A fatura de {x.CreditCard!.Name} vence em {x.DueDate:dd/MM/yyyy}.")));
  var installments=await db.DebtInstallments.AsNoTracking().Include(x=>x.Debt).Where(x=>x.PaidAt==null&&x.DueDate>=today&&x.DueDate<=until).ToListAsync(ct);pending.AddRange(installments.Select(x=>New(NotificationType.DueDate,$"debt:{x.Id}:due:{x.DueDate}","Parcela de dívida próxima",$"A parcela {x.Number} de {x.Debt!.Name} vence em {x.DueDate:dd/MM/yyyy}.")));
  var subscriptions=await db.Subscriptions.AsNoTracking().Where(x=>x.IsActive&&x.StartDate<=until).ToListAsync(ct);foreach(var x in subscriptions){var next=FinancialCalculations.NextBillingDate(x.StartDate,x.Cycle,x.BillingDay,today);if(next is not null&&next<=until)pending.Add(New(NotificationType.DueDate,$"subscription:{x.Id}:billing:{next:yyyy-MM-dd}","Assinatura próxima da cobrança",$"{x.Name} será cobrada em {next:dd/MM/yyyy}."));}
  var now=DateTime.UtcNow;var budgets=await db.Budgets.AsNoTracking().Include(x=>x.Category).Where(x=>x.Month==today.Month&&x.Year==today.Year).ToListAsync(ct);var start=new DateOnly(today.Year,today.Month,1);var spent=await db.Transactions.AsNoTracking().Where(x=>x.Date>=start&&x.Date<start.AddMonths(1)&&x.Type==TransactionType.Expense&&x.Status!=TransactionStatus.Cancelled&&x.CategoryId!=null).GroupBy(x=>x.CategoryId).Select(x=>new{CategoryId=x.Key,Amount=x.Sum(t=>t.Amount)}).ToDictionaryAsync(x=>x.CategoryId!.Value,x=>x.Amount,ct);pending.AddRange(budgets.Where(x=>spent.GetValueOrDefault(x.CategoryId)>=x.Amount*.8m).Select(x=>New(NotificationType.Budget,$"budget:{x.Id}:{today:yyyy-MM}",spent.GetValueOrDefault(x.CategoryId)>=x.Amount?"Orçamento atingido":"Orçamento próximo do limite",$"{x.Category!.Name}: {spent.GetValueOrDefault(x.CategoryId):C} de {x.Amount:C}.")));
  var goals=await db.FinancialGoals.AsNoTracking().Include(x=>x.Contributions).Where(x=>x.Contributions.Sum(c=>c.Amount)>=x.TargetAmount).ToListAsync(ct);pending.AddRange(goals.Select(x=>New(NotificationType.Goal,$"goal:{x.Id}:completed","Meta atingida",$"A meta {x.Name} foi atingida.")));
  foreach(var notification in pending){if(!await db.Notifications.AnyAsync(x=>x.UniqueKey==notification.UniqueKey,ct)){try{db.Notifications.Add(notification);await db.SaveChangesAsync(ct);}catch(DbUpdateException){db.Entry(notification).State=EntityState.Detached;}}}
  Notification New(NotificationType type,string key,string title,string message)=>new(){UserId=current.UserId,Type=type,UniqueKey=key,Title=title,Message=message};
 }
}

[ApiController,Authorize,EnableRateLimiting("csv"),Route("api/v1/import-export")]
public sealed class ImportExportController(FinanceiroDbContext db):ControllerBase
{
 [HttpGet("transactions.csv")]public async Task<IActionResult>Export(DateOnly? from,DateOnly? to,Guid? accountId,CancellationToken ct){var q=db.Transactions.AsNoTracking().AsQueryable();if(from is not null)q=q.Where(x=>x.Date>=from);if(to is not null)q=q.Where(x=>x.Date<=to);if(accountId is not null){if(!await db.Accounts.AnyAsync(x=>x.Id==accountId&&x.IsActive,ct))return NotFound();q=q.Where(x=>x.AccountId==accountId);}var rows=await q.Select(x=>new{description=x.Description,amount=x.Amount,type=x.Type,status=x.Status,date=x.Date,notes=x.Notes}).ToListAsync(ct);await using var stream=new MemoryStream();await using(var writer=new StreamWriter(stream,Encoding.UTF8,leaveOpen:true)){await using var csv=new CsvWriter(writer,CultureInfo.GetCultureInfo("pt-BR"));csv.WriteField("description");csv.WriteField("amount");csv.WriteField("type");csv.WriteField("status");csv.WriteField("date");csv.WriteField("notes");await csv.NextRecordAsync();foreach(var row in rows){csv.WriteField(NeutralizeSpreadsheetFormula(row.description));csv.WriteField(row.amount);csv.WriteField(row.type.ToString());csv.WriteField(row.status.ToString());csv.WriteField(row.date.ToString("dd/MM/yyyy"));csv.WriteField(NeutralizeSpreadsheetFormula(row.notes));await csv.NextRecordAsync();}}return File(stream.ToArray(),"text/csv","transacoes.csv");}
 private static string? NeutralizeSpreadsheetFormula(string? value)=>string.IsNullOrEmpty(value)||value[0] is not ('=' or '+' or '-' or '@')?value:"'"+value;
 [HttpPost("transactions/preview")]public async Task<IActionResult>Preview(IFormFile file,CancellationToken ct){const long maxBytes=5*1024*1024;const int maxRecords=100;const int maxFieldLength=4096;if(file is null||file.Length==0)return BadRequest("Arquivo vazio.");if(file.Length>maxBytes)return BadRequest("Arquivo excede 5 MB.");if(!string.IsNullOrWhiteSpace(file.ContentType)&&file.ContentType is not "text/csv" and not "application/csv" and not "application/vnd.ms-excel")return BadRequest("Formato de arquivo inválido.");using var reader=new StreamReader(file.OpenReadStream(),Encoding.UTF8,detectEncodingFromByteOrderMarks:true,bufferSize:8192,leaveOpen:false);var csvConfig=new CsvConfiguration(CultureInfo.GetCultureInfo("pt-BR")){BadDataFound=context=>throw new BadHttpRequestException("CSV malformado.")};using var csv=new CsvReader(reader,csvConfig);var records=new List<Dictionary<string,string?>>(maxRecords);try{await foreach(var row in csv.GetRecordsAsync<dynamic>(ct)){var values=((IDictionary<string,object>)row).ToDictionary(x=>x.Key,x=>x.Value?.ToString());if(values.Count>50||values.Any(x=>x.Value?.Length>maxFieldLength))return BadRequest("Campo CSV excede o limite permitido.");records.Add(values);if(records.Count>=maxRecords)break;}}catch(FormatException){return BadRequest("CSV malformado.");}return Ok(new{rows=records,totalPreview=records.Count});}
}
